syntax:
// same name, different parameter lists
int add(int a, int b);          // two ints
double add(double a, double b); // two doubles

int area(int side);             // square (one int)
int area(int length, int width);// rectangle (two ints)
double area(double radius);     // circle (one double)

// NOT overloads:
// int f(int a);   double f(int a);   // only the return type differs: error
// int f(int a);   int f(int b);      // only the name differs: same function

sample.code:
#include <iostream>
using namespace std;

int add(int a, int b) {
    return a + b;
}

double add(double a, double b) {
    return a + b;
}

int main() {
    cout << add(2, 3) << endl;
    cout << add(2.5, 1.5) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int area(int side) {
    return side * side;
}

int area(int length, int width) {
    return length * width;
}

double area(double radius) {
    return 3.14159 * radius * radius;
}

int main() {
    cout << "Square: " << area(5) << endl;
    cout << "Rectangle: " << area(4, 6) << endl;
    cout << "Circle: " << area(2.0) << endl;
    return 0;
}

#include <iostream>
using namespace std;

void show(int x) {
    cout << "int " << x << endl;
}

void show(double x) {
    cout << "double " << x << endl;
}

int main() {
    show(7);
    show(2.5);
    show('A');
    show(true);
    return 0;
}

